  { text: "I'm so lucky to have you...", x: "60%", y: "-40vh", rotate: 5, swayDur: 6 + Math.random() * 4, swayDel: Math.random() * -10, theme: themes[0] },
  { text: "My favorite person...", x: "5%", y: "-40vh", rotate: -6, swayDur: 6 + Math.random() * 4, swayDel: Math.random() * -10, theme: themes[1] },
  { text: "You mean everything...", x: "55%", y: "-40vh", rotate: 9, swayDur: 6 + Math.random() * 4, swayDel: Math.random() * -10, theme: themes[2] },
  { text: "I'll always be here...", x: "10%", y: "-40vh", rotate: -4, swayDur: 6 + Math.random() * 4, swayDel: Math.random() * -10, theme: themes[0] },
  { text: "Happy Birthday Love!", x: "65%", y: "-40vh", rotate: 7, swayDur: 6 + Math.random() * 4, swayDel: Math.random() * -10, theme: themes[3] }
]);

const bgLanterns = Array.from({ length: 60 }, (_, i) => ({
  x: Math.random() * 100 + '%',
  y: (i < 20 ? Math.random() * 200 + 100 : Math.random() * 400 + 300) + 'vh',
  scale: Math.random() * 0.4 + 0.2,
  opacity: Math.random() * 0.3 + 0.1,
  rotate: Math.random() * 40 - 20,
  isHighDensity: i >= 20,
  swayDur: 8 + Math.random() * 6,
  swayDel: Math.random() * -20,
  theme: themes[Math.floor(Math.random() * themes.length)]
}));

const starsDist = Array.from({ length: 150 }, () => ({
  x: Math.random() * 100 + '%',
  y: Math.random() * 100 + '%',
  r: Math.random() * 0.8 + 0.2
}));

const starsClose = Array.from({ length: 80 }, () => ({
  x: Math.random() * 100 + '%',
  y: Math.random() * 100 + '%',
  r: Math.random() * 1.2 + 0.5
}));

const fireflyStyles = Array.from({ length: 12 }, () => ({
  left: Math.random() * 100 + '%',
  top: Math.random() * 100 + '%',
  animationDelay: Math.random() * 5 + 's',
  animationDuration: Math.random() * 3 + 2 + 's'
}));

const toggleMusic = () => {
  if (!audioPlayer.value) return;
  if (isPlaying.value) {
    audioPlayer.value.pause();
    isPlaying.value = false;
  } else {
    audioPlayer.value.play().then(() => {
      isPlaying.value = true;
    }).catch(e => console.error("Audio blocked", e));
  }
};

const handleLanternInteraction = (e, index) => {
  const rect = e.currentTarget.getBoundingClientRect();
  const x = e.clientX || (e.touches && e.touches[0].clientX);
  const y = e.clientY || (e.touches && e.touches[0].clientY);
  
  if (!x || !y) return;

  const centerX = rect.left + rect.width / 2;
  const centerY = rect.top + rect.height / 2;
  
  const dx = (x - centerX) / 8;
  const dy = (y - centerY) / 8;

  gsap.to(`#lantern-paper-${index}`, {
    x: -dx,
    y: -dy,
    rotate: -dx / 1.5,
    duration: 0.5,
    ease: "power2.out"
  });
};

onMounted(() => {
  // Parallax Sky
  gsap.to("#stars-distant", {
    y: "-10vh",
    ease: "none",
    scrollTrigger: {
      trigger: ".content-wrapper",
      start: "top top",
      end: "bottom bottom",
      scrub: true
    }
  });

  gsap.to("#stars-closer", {
    y: "-30vh",
    ease: "none",
    scrollTrigger: {
      trigger: ".content-wrapper",
      start: "top top",
      end: "bottom bottom",
      scrub: true
    }
  });

  // Fade in music on first scroll
  const handleFirstScroll = () => {
    if (!isPlaying.value && audioPlayer.value) {
      audioPlayer.value.volume = 0;
      audioPlayer.value.play().then(() => {
        gsap.to(audioPlayer.value, { volume: 0.5, duration: 3 });
        isPlaying.value = true;
      }).catch(() => {});
    }
    window.removeEventListener('scroll', handleFirstScroll);
  };
  window.addEventListener('scroll', handleFirstScroll);

  // Background Continuity Fix: Hide stars after Phase 4
  ScrollTrigger.create({
    trigger: "#boat-scene",
    start: "bottom center",
    onEnter: () => {
      gsap.to(".background-layer", { opacity: 0, duration: 1.5 });
      gsap.to(".firefly-overlay", { opacity: 0, duration: 1.5 });
    },
    onLeaveBack: () => {
      gsap.to(".background-layer", { opacity: 1, duration: 1.5 });
      gsap.to(".firefly-overlay", { opacity: 1, duration: 1.5 });
    }
  });

  // Lantern Animations
  snippets.value.forEach((_, i) => {
    gsap.fromTo(`#lantern-paper-${i}`, 
      { 
        y: 100, 
        opacity: 0,
        rotate: -10
      },
      {
        y: 0,
        opacity: 1,
        rotate: 0,
        duration: 1.2,
        ease: "power2.out",
        scrollTrigger: {
          trigger: `#letter-section-${i}`,
          start: "top 95%", // Trigger very early
          toggleActions: "play none none reverse", // Play instantly
          onEnter: () => {
            gsap.to(".bg-lantern", { opacity: 0.1, duration: 1 });
          },
          onLeaveBack: () => {
            gsap.to(".bg-lantern", { opacity: 0.2, duration: 1 });
          }
        }
      }
    );
  });
});
</script>

